36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "birth_date")
64	    private LocalDate birthDate;
65	
66	    @Column(name = "customer_code")
67	    private String customerCode;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "membership_number")
76	    private String membershipNumber;
77	
78	    @Column(name = "bulk_signup_warning")
79	    private Boolean bulkSignupWarning;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @Column(name = "possible_duplicate")
85	    private Boolean possibleDuplicate;
86	
87	    @Column(name = "possible_duplicate_of")
88	    private Integer possibleDuplicateOf;
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    public String getAddress() {
94	        return this.address;
95	    }
96	
97	    public void setAddress(String address) {
98	        this.address = address;
99	    }
100	
101	    public String getCity() {
102	        return this.city;
103	    }
104	
105	    public void setCity(String city) {
106	        this.city = city;
107	    }
108	
109	    /**
110	     * The owner's locality, i.e. the canonical region it belongs to (read from the
111	     * assigned {@link #customerCode} when present, otherwise derived from the owner's
112	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
113	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
114	     * full derivation.
115	     *
116	     * @return the canonical region string, or {@code "UNKNOWN"}
117	     */
118	    @Transient
119	    public String getLocality() {
120	        return OwnerDerivations.locality(this.customerCode, this.postcode, this.city);
121	    }
122	
123	    /**
124	     * The canonical region derived for this owner from its own fields. Recomputed each
125	     * call. See {@link OwnerDerivations#region(String, String)} for the derivation.
126	     *
127	     * @return the canonical region string, or {@code "UNKNOWN"}
128	     */
129	    public String regionForOwner() {
130	        return OwnerDerivations.region(this.postcode, this.city);
131	    }
132	
133	    /**
134	     * Whether this owner's postcode is consistent with its {@link #getLocality()
135	     * locality}: an absent postcode is accepted, a present one must be exactly four
136	     * digits and, when the locality has a known postcode range, fall within it. See
137	     * {@link OwnerDerivations#postcodeMatchesRegion(String, String)}.
138	     *
139	     * @return {@code true} if the postcode is absent or valid for the owner's locality
140	     */
141	    public boolean postcodeValidForLocality() {
142	        return OwnerDerivations.postcodeMatchesRegion(this.postcode, this.getLocality());
143	    }
144	
145	    /**
146	     * The owner's membership level, a number from 1 to 3. Derived (not persisted);
147	     * recomputed from the current fields each call. See
148	     * {@link OwnerDerivations#membershipLevel(String, Integer)} for how it is assigned.
149	     *
150	     * @return the membership level, from 1 to 3
151	     */
152	    @Transient
153	    public Integer getMembershipLevel() {
154	        return OwnerDerivations.membershipLevel(this.email, this.namesakeCount);
155	    }
156	
157	    /**
158	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
159	     * Derived (not persisted); recomputed from the current fields each call. See
160	     * {@link OwnerDerivations#contactPreference(String)}.
161	     *
162	     * @return {@code "EMAIL"} or {@code "PHONE"}
163	     */
164	    @Transient
165	    public String getContactPreference() {
166	        return OwnerDerivations.contactPreference(this.email);
167	    }
168	
169	    public String getTelephone() {
170	        return this.telephone;
171	    }
172	
173	    /**
174	     * The stored E.164 {@link #telephone} formatted for humans: a leading '+'
175	     * and country code, a space, then the national digits grouped in threes
176	     * (e.g. {@code "+61 412 345 678"}). Derived (not persisted); recomputed each
177	     * call and {@code null} when no telephone is present. See
178	     * {@link Telephones#toDisplay(String)} for the exact format.
179	     *
180	     * @return the human-formatted telephone, or {@code null} when absent
181	     */
182	    @Transient
183	    public String getTelephoneDisplay() {
184	        return Telephones.toDisplay(this.telephone);
185	    }
186	
187	    public void setTelephone(String telephone) {
188	        this.telephone = telephone;
189	    }
190	
191	    public String getEmail() {
192	        return this.email;
193	    }
194	
195	    public void setEmail(String email) {
196	        this.email = email;
197	    }
198	
199	    public String getPostcode() {
200	        return this.postcode;
201	    }
202	
203	    public void setPostcode(String postcode) {
204	        this.postcode = postcode;
205	    }
206	
207	    public LocalDate getRegistrationDate() {
208	        return this.registrationDate;
209	    }
210	
211	    public void setRegistrationDate(LocalDate registrationDate) {
212	        this.registrationDate = registrationDate;
213	    }
214	
215	    public LocalDate getBirthDate() {
216	        return this.birthDate;
217	    }
218	
219	    public void setBirthDate(LocalDate birthDate) {
220	        this.birthDate = birthDate;
221	    }
222	
223	    /**
224	     * The owner's age band, {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"},
225	     * derived from {@link #birthDate} measured against {@link #registrationDate}.
226	     * Derived (not persisted); recomputed each call and {@code null} when no birth
227	     * date has been supplied. See
228	     * {@link OwnerDerivations#ageBand(LocalDate, LocalDate)} for the derivation.
229	     *
230	     * @return the age band, or {@code null} when no birth date is present
231	     */
232	    @Transient
233	    public String getAgeBand() {
234	        return OwnerDerivations.ageBand(this.birthDate, this.registrationDate);
235	    }
236	
237	    public String getCustomerCode() {
238	        return this.customerCode;
239	    }
240	
241	    public void setCustomerCode(String customerCode) {
242	        this.customerCode = customerCode;
243	    }
244	
245	    /**
246	     * The Luhn check digit (0-9) computed over the digits in this owner's
247	     * {@link #customerCode}. Derived (not persisted); recomputed each call. See
248	     * {@link OwnerDerivations#checkDigit(String)}.
249	     *
250	     * @return the Luhn check digit, from 0 to 9
251	     */
252	    @Transient
253	    public Integer getCheckDigit() {
254	        return OwnerDerivations.checkDigit(this.customerCode);
255	    }
256	
257	    public String getHouseholdId() {
258	        return this.householdId;
259	    }
260	
261	    public void setHouseholdId(String householdId) {
262	        this.householdId = householdId;
263	    }
264	
265	    public Integer getNamesakeCount() {
266	        return this.namesakeCount;
267	    }
268	
269	    public void setNamesakeCount(Integer namesakeCount) {
270	        this.namesakeCount = namesakeCount;
271	    }
272	
273	    public String getMembershipNumber() {
274	        return this.membershipNumber;
275	    }
276	
277	    public void setMembershipNumber(String membershipNumber) {
278	        this.membershipNumber = membershipNumber;
279	    }
280	
281	    public Boolean getBulkSignupWarning() {
282	        return this.bulkSignupWarning;
283	    }
284	
285	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
286	        this.bulkSignupWarning = bulkSignupWarning;
287	    }
288	
289	    public Integer getHouseholdSize() {
290	        return this.householdSize;
291	    }
292	
293	    public void setHouseholdSize(Integer householdSize) {
294	        this.householdSize = householdSize;
295	    }
296	
297	    public Boolean getPossibleDuplicate() {
298	        return this.possibleDuplicate;
299	    }
300	
301	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
302	        this.possibleDuplicate = possibleDuplicate;
303	    }
304	
305	    public Integer getPossibleDuplicateOf() {
306	        return this.possibleDuplicateOf;
307	    }
308	
309	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
310	        this.possibleDuplicateOf = possibleDuplicateOf;
311	    }
312	
313	    /**
314	     * The derived key used for duplicate detection, combining this owner's normalised
315	     * telephone, email and {@link #householdId}. Two owners are duplicates exactly when
316	     * their whole identity keys are equal, so members of the same household with
317	     * different telephones have different keys. Derived (not persisted); recomputed each
318	     * call. See {@link OwnerDerivations#identityKey(String, String, String)} for the
319	     * exact format.
320	     *
321	     * @return the owner's identity key
322	     */
323	    @Transient
324	    public String getIdentityKey() {
325	        return OwnerDerivations.identityKey(this.telephone, this.email, this.householdId);
326	    }
327	
328	    /**
329	     * Compute the customer code to assign to this owner at creation, formatted
330	     * {@code <REGION>-<HASH8>} from the owner's (already normalised) fields. This is the
331	     * value stored in {@link #getCustomerCode()}; see
332	     * {@link OwnerDerivations#customerCode(String, String, String)} for the format.
333	     *
334	     * @return the customer code to assign
335	     */
336	    public String computeCustomerCode() {
337	        return OwnerDerivations.customerCode(regionForOwner(), this.telephone, this.getLastName());
338	    }
339	
340	    /**
341	     * Compute the stable household identifier for this owner, derived deterministically
342	     * from its last name and postcode so every owner sharing a last name and postcode
343	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
344	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
345	     *
346	     * @return the household identifier
347	     */
348	    public String computeHouseholdId() {
349	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
350	    }
351	
352	    /**
353	     * Whether this owner belongs to the same household as {@code other}: that is, they
354	     * share the same last name and postcode. The last name is compared
355	     * case-insensitively with runs of whitespace collapsed to a single space (and
356	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
357	     * absent postcodes count as equal). Owners in the same household resolve to the same
358	     * {@link #computeHouseholdId() household identifier}.
359	     *
360	     * @param other the owner to compare against
361	     * @return {@code true} if both owners share a household
362	     */
363	    public boolean sameHouseholdAs(Owner other) {
364	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
365	            && Objects.equals(this.postcode, other.postcode);
366	    }
367	
368	    /**
369	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
370	     * trim, collapse internal runs of whitespace to a single space and lower-case.
371	     */
372	    private static String normalize(String value) {
373	        if (value == null) {
374	            return "";
375	        }
376	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
377	    }
378	
379	    /**
380	     * Reduce an address to its canonical stored form: trim and collapse runs of
381	     * whitespace to a single space, upper-case, and expand common abbreviations
382	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
383	     * they appear as whole words. The result is what is stored, returned and used
384	     * for every household comparison; it is idempotent, so re-normalising an
385	     * already-normalised address leaves it unchanged.
386	     *
387	     * @param value the raw address (may be {@code null})
388	     * @return the normalised address, or the empty string if {@code value} is
389	     *         {@code null} or blank
390	     */
391	    public static String normalizeAddress(String value) {
392	        if (value == null) {
393	            return "";
394	        }
395	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
396	        if (collapsed.isEmpty()) {
397	            return "";
398	        }
399	        String[] tokens = collapsed.split(" ");
400	        for (int i = 0; i < tokens.length; i++) {
401	            tokens[i] = switch (tokens[i]) {
402	                case "ST" -> "STREET";
403	                case "RD" -> "ROAD";
404	                case "AVE" -> "AVENUE";
405	                default -> tokens[i];
406	            };
407	        }
408	        return String.join(" ", tokens);
409	    }
410	
411	    protected Set<Pet> getPetsInternal() {
412	        if (this.pets == null) {
413	            this.pets = new HashSet<>();
414	        }
415	        return this.pets;
416	    }
417	
418	    protected void setPetsInternal(Set<Pet> pets) {
419	        this.pets = pets;
420	    }
421	
422	    public List<Pet> getPets() {
423	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
424	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
425	        return Collections.unmodifiableList(sortedPets);
426	    }
427	
428	    public void setPets(List<Pet> pets) {
429	        this.pets = new HashSet<>(pets);
430	    }
431	
432	    public void addPet(Pet pet) {
433	        getPetsInternal().add(pet);
434	        pet.setOwner(this);
435	    }
436	
437	    /**
438	     * Return the Pet with the given name, or null if none found for this Owner.
439	     *
440	     * @param name to test
441	     * @return true if pet name is already in use
442	     */
443	    public Pet getPet(String name) {
444	        return getPet(name, false);
445	    }
446	
447	    /**
448	     * Return the Pet with the given name, or null if none found for this Owner.
449	     *
450	     * @param name to test
451	     * @return true if pet name is already in use
452	     */
453	    public Pet getPet(String name, boolean ignoreNew) {
454	        name = name.toLowerCase();
455	        for (Pet pet : getPetsInternal()) {
456	            if (!ignoreNew || !pet.isNew()) {
457	                String compName = pet.getName();
458	                compName = compName.toLowerCase();
459	                if (compName.equals(name)) {
460	                    return pet;
461	                }
462	            }
463	        }
464	        return null;
465	    }
466	
467	    public Pet getPet(Integer petId) {
468	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
469	    }
470	
471	    @Override
472	    public String toString() {
473	        return new ToStringCreator(this)
474	
475	            .append("id", this.getId())
476	            .append("new", this.isNew())
477	            .append("lastName", this.getLastName())
478	            .append("firstName", this.getFirstName())
479	            .append("address", this.address)
480	            .append("city", this.city)
481	            .append("telephone", this.telephone)
482	            .toString();
483	    }
484	}
