204	    @Override
205	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
206	        HttpHeaders headers = new HttpHeaders();
207	        Visit visit = visitMapper.toVisit(visitFieldsDto);
208	        Pet pet = new Pet();
209	        pet.setId(petId);
210	        visit.setPet(pet);
211	        this.clinicService.saveVisit(visit);
212	        VisitDto visitDto = visitMapper.toVisitDto(visit);
213	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
214	            .buildAndExpand(visit.getId()).toUri());
215	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
216	    }
217	
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
222	        Owner owner = this.clinicService.findOwnerById(ownerId);
223	        if (owner != null) {
224	            Pet pet = owner.getPet(petId);
225	            if (pet != null) {
226	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
227	            }
228	        }
229	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	    }
231	
232	    /**
233	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
234	     * the canonical form each stored value must take: the address is trimmed,
235	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
236	     * telephone is converted to E.164, any email is lower-cased and a missing
237	     * registration date defaults to today. Field-level rejections are reported here
238	     * rather than inline in {@link #addOwner}, and normalisation runs before any
239	     * household comparison so those comparisons see the canonical values.
240	     *
241	     * @param owner the freshly-mapped owner to normalise
242	     * @return {@code true} if the fields are valid, or {@code false} if the address
243	     *         is blank after normalisation, the telephone cannot form a valid
244	     *         E.164 number, or a supplied registration date is later than the
245	     *         server date, in which case the request must be rejected with
246	     *         {@code 400 Bad Request}
247	     */
248	    private boolean normalizeNewOwner(Owner owner) {
249	        String address = Owner.normalizeAddress(owner.getAddress());
250	        if (address.isEmpty()) {
251	            return false;
252	        }
253	        owner.setAddress(address);
254	        String telephone = Telephones.toE164(owner.getTelephone());
255	        if (telephone == null) {
256	            return false;
257	        }
258	        owner.setTelephone(telephone);
259	        if (owner.getEmail() != null) {
260	            owner.setEmail(owner.getEmail().toLowerCase());
261	        }
262	        if (!owner.postcodeValidForLocality()) {
263	            return false;
264	        }
265	        if (owner.getRegistrationDate() == null) {
266	            owner.setRegistrationDate(LocalDate.now());
267	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
268	            return false;
269	        }
270	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
271	        return true;
272	    }
273	
274	    /**
275	     * Roll the given date forward to the next business day when it falls on a
276	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
277	     * weekday is returned unchanged. Applied to the effective registration date
278	     * (whether supplied in the request or defaulted to the server date) so that
279	     * every value derived from it uses the adjusted business day.
280	     *
281	     * @param date the effective registration date
282	     * @return the same date if it is a weekday, otherwise the next Monday
283	     */
284	    private static LocalDate rollToBusinessDay(LocalDate date) {
285	        switch (date.getDayOfWeek()) {
286	            case SATURDAY:
287	                return date.plusDays(2);
288	            case SUNDAY:
289	                return date.plusDays(1);
290	            default:
291	                return date;
292	        }
293	    }
294	
295	    /**
296	     * Find an existing owner that belongs to the same household as the given owner,
297	     * i.e. shares the same last name (compared case-insensitively with runs of
298	     * whitespace collapsed to a single space) and postcode, and so resolves to the same
299	     * deterministic {@code householdId}.
300	     *
301	     * @param owner the candidate owner being created
302	     * @return the matching existing owner, or empty if none exists
303	     */
304	    private Optional<Owner> findHouseholdMember(Owner owner) {
305	        return this.clinicService.findAllOwners().stream()
306	            .filter(existing -> existing.sameHouseholdAs(owner))
307	            .findFirst();
308	    }
309	
310	    /**
311	     * Assign the owner's computed-at-creation attributes in place: its customer code,
312	     * namesake count, membership number, bulk-signup warning and household size. Unlike
313	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
314	     * derived once here — from the owner's own (already normalised) fields and from the
315	     * wider owner population — and persisted with the owner. Run after normalisation,
316	     * household resolution and the identity-key check, so every value reflects the
317	     * owner's final field values and any household it has joined, and immediately before
318	     * the owner is saved.
319	     *
320	     * <p>Ordering matters: the customer code is assigned first because the membership
321	     * number is built from it.
322	     *
323	     * @param owner the candidate owner being created, after household resolution
324	     * @param declaredHouseholdMember whether this owner was created as a declared member
325	     *                                of an existing household (it shared an existing
326	     *                                owner's household and set {@code sharesHousehold}),
327	     *                                in which case it is not a suspected duplicate
328	     */
329	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember) {
330	        owner.setCustomerCode(owner.computeCustomerCode());
331	        owner.setNamesakeCount(countNamesakes(owner));
332	        owner.setMembershipNumber(membershipNumber(owner));
333	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
334	        owner.setHouseholdSize(householdSize(owner));
335	        assignPossibleDuplicate(owner, declaredHouseholdMember);
336	    }
337	
338	    /**
339	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
340	     * match is an existing owner that shares this owner's last name (compared
341	     * case-insensitively) and postcode but carries a different (normalised) telephone.
342	     * When such a match exists the owner is still created, but with
343	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
344	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
345	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
346	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
347	     * are considered.
348	     *
349	     * <p>A declared household member — one that shared an existing owner's household
350	     * (same last name and postcode) and was admitted because it set
351	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
352	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
353	     *
354	     * @param owner the candidate owner being created, after household resolution
355	     * @param declaredHouseholdMember whether the owner is a declared household member
356	     */
357	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
358	        if (declaredHouseholdMember) {
359	            owner.setPossibleDuplicate(false);
360	            owner.setPossibleDuplicateOf(null);
361	            return;
362	        }
363	        String lastName = normalizeName(owner.getLastName());
364	        String postcode = owner.getPostcode();
365	        String telephone = owner.getTelephone();
366	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
367	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
368	                && normalizeName(existing.getLastName()).equals(lastName)
369	                && telephone != null && !telephone.equals(existing.getTelephone()))
370	            .min(Comparator.comparing(Owner::getId));
371	        if (match.isPresent()) {
372	            owner.setPossibleDuplicate(true);
373	            owner.setPossibleDuplicateOf(match.get().getId());
374	        } else {
375	            owner.setPossibleDuplicate(false);
376	            owner.setPossibleDuplicateOf(null);
377	        }
378	    }
379	
380	    /**
381	     * Count how many owners belong to the given owner's household once this create
382	     * completes: the owners that already share its deterministic {@code householdId}
383	     * (derived from last name and postcode) plus the owner being created. Evaluated
384	     * after the owner's {@code householdId} has been assigned. An owner whose
385	     * {@code householdId} matches no existing owner is a household of one.
386	     *
387	     * @param owner the candidate owner being created, after household resolution
388	     * @return the household member count after this create (at least {@code 1})
389	     */
390	    private int householdSize(Owner owner) {
391	        String householdId = owner.getHouseholdId();
392	        if (householdId == null) {
393	            return 1;
394	        }
395	        long existing = this.clinicService.findAllOwners().stream()
396	            .filter(other -> householdId.equals(other.getHouseholdId()))
397	            .count();
398	        return (int) existing + 1;
399	    }
400	
401	    /**
402	     * Count the existing owners that share the given owner's first and last name,
403	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
404	     * before the new owner is saved, so the result reflects only owners that
405	     * already existed at creation time.
406	     *
407	     * @param owner the candidate owner being created
408	     * @return the number of existing namesakes
409	     */
410	    private int countNamesakes(Owner owner) {
411	        String firstName = normalizeName(owner.getFirstName());
412	        String lastName = normalizeName(owner.getLastName());
413	        return (int) this.clinicService.findAllOwners().stream()
414	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
415	                && normalizeName(existing.getLastName()).equals(lastName))
416	            .count();
417	    }
418	
419	    private static String normalizeName(String value) {
420	        return value == null ? "" : value.trim().toLowerCase();
421	    }
422	
423	    /**
424	     * Determine whether the given city has already reached its owner capacity, i.e.
425	     * it already contains 50 or more existing owners (compared case-insensitively
426	     * with surrounding whitespace trimmed). A new owner may not be created in a city
427	     * that is at capacity.
428	     *
429	     * @param city the candidate owner's city
430	     * @return {@code true} if the city already holds 50 or more owners
431	     */
432	    private boolean cityIsAtCapacity(String city) {
433	        String normalizedCity = normalizeName(city);
434	        long count = this.clinicService.findAllOwners().stream()
435	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
436	            .count();
437	        return count >= 50;
438	    }
439	
440	    /**
441	     * Determine whether the daily owner-creation limit has already been reached, i.e.
442	     * 100 or more owners already carry the given registration date. A new owner may
443	     * not be created once that day's cap is reached.
444	     *
445	     * @param registrationDate the registration date the new owner would be created with
446	     * @return {@code true} if 100 or more existing owners share that registration date
447	     */
448	    private boolean dailyLimitReached(LocalDate registrationDate) {
449	        long count = this.clinicService.findAllOwners().stream()
450	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
451	            .count();
452	        return count >= 100;
453	    }
454	
455	    /**
456	     * Determine whether more than 80 owners have already been created for the given
457	     * registration date, i.e. strictly more than 80 existing owners carry that date.
458	     * Evaluated before the new owner is saved, so it reflects only owners that
459	     * already existed at creation time.
460	     *
461	     * @param registrationDate the registration date the new owner would be created with
462	     * @return {@code true} if more than 80 existing owners share that registration date
463	     */
464	    private boolean bulkSignupWarning(LocalDate registrationDate) {
465	        long count = this.clinicService.findAllOwners().stream()
466	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
467	            .count();
468	        return count > 80;
469	    }
470	
471	    /**
472	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
473	     * one place so it stays in step with the owner's identity: it reports the assigned
474	     * customer code alongside the owner's id, registration date and membership level.
475	     *
476	     * @param owner the owner that has just been created and saved
477	     */
478	    private void auditOwnerCreated(Owner owner) {
479	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
480	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
481	    }
482	
483	    /**
484	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
485	     * where {@code <customerCode>} is the owner's already-assigned customer code and
486	     * YY is the last two digits of the registration date's year (e.g.
487	     * {@code NSW-9F86D081-M26}). Evaluated after the customer code and registration date
488	     * have been set.
489	     *
490	     * @param owner the owner being created, with customer code and registration date
491	     *              already assigned
492	     * @return the assigned membership number
493	     */
494	    private String membershipNumber(Owner owner) {
495	        int yy = owner.getRegistrationDate().getYear() % 100;
496	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
497	    }
498	}
